def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    foreground = {v for v in counts if v != bg}
    points = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v in foreground]
    if not points: return [row[:] for row in grid]
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    left=min(c for r,c in points); right=max(c for r,c in points)
    for r in range(h):
        cols=[c for rr,c in points if rr==r]
        if len(cols)>=3:
            for c in range(min(cols),max(cols)+1):
                if grid[r][c]==bg: out[r][c]=2
    for c in {left,right}:
        rows=[r for r,cc in points if cc==c]
        for r in range(min(rows),max(rows)+1):
            if grid[r][c]==bg: out[r][c]=2
    return out

